patch='';manifest={}
for file,after in changes.items():
 before=(root/file).read_text();patch+=''.join(difflib.unified_diff(before.splitlines(True),after.splitlines(True),fromfile='a/'+file,tofile='b/'+file));manifest[file]={'before':hashlib.sha256(before.encode()).hexdigest(),'after':hashlib.sha256(after.encode()).hexdigest()};(target/Path(file).name).write_text(after)
(target/'corrections.patch').write_text(patch);(target/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n');print(json.dumps({'files':len(changes),'patchSHA256':hashlib.sha256(patch.encode()).hexdigest()}))
